-- table: tool_parameters
CREATE TABLE IF NOT EXISTS tool_parameters (
            tool_id INTEGER NOT NULL,
            position INTEGER NOT NULL,
            name TEXT NOT NULL,
            type TEXT,
            mandatory INTEGER NOT NULL DEFAULT 0 CHECK (mandatory IN (0, 1)),
            default_value TEXT,
            default_kind TEXT NOT NULL DEFAULT 'null' CHECK (default_kind IN ('null', 'text', 'bool', 'int', 'real')),
            description TEXT,
            PRIMARY KEY (tool_id, position)
        );
INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10286, 0, 'TargetSubsystem', 'String', 0, 'HaSSD06 (Home Assistant OS)', 'text', 'Name of the target Subsystem requiring authentication.');
INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10286, 1, 'MutationAction', 'String', 0, 'Execute Privileged Service / Mutation Call', 'text', 'Description of the privileged service or mutation call to execute.');
INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10286, 2, 'RiskLevel', 'String', 0, 'Medium', 'text', 'Assessed risk level (Low, Medium, High, Critical).');
INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10286, 3, 'MutationPreview', 'String', 0, 'Service: homeassistant.update_entity`nTarget: 192.168.10.6:8123`nTimeout: 30s', 'text', 'Text diff or command preview of the mutation.');
INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10287, 0, 'SkipBackupProbe', 'SwitchParameter', 0, '', 'text', 'Bypasses the live Home Assistant backup probe requirement before mutations.');
INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10303, 0, 'Instance', 'String', 0, 'HaSSD06', 'text', 'Target Home Assistant instance or subsystem identifier (default: HaSSD06).');
