INSERT OR REPLACE INTO tool_parameters (tool_id, position, name, type, mandatory, default_value, default_kind, description) VALUES (10440, 0, 'Action', 'String', 0, 'Sync', 'text', 'Operation to perform: - ''Sync'' : JSON -> SQLite DB + SQL text dump (default). - ''Dump'' : SQLite DB -> Canonical proposals.sql text dump. - ''Hydrate'' : Reconstructs SQLite DB from canonical proposals.sql text dump. - ''Verify'' : 3-way parity check across JSON, SQLite DB, and SQL text dump. - ''Query'' : High-speed query returning objects from SQLite. - ''InstallHooks'' : Installs Git post-merge and post-checkout hooks for automatic hydration on pull/checkout.');
